import Complex128Array = require( '@stdlib/array/complex128' );
import zdscal = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal( zx.length, da, zx, 1 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal( '10', da, zx, 1 ); // $EzxpectError
	zdscal( true, da, zx, 1 ); // $ExpectError
	zdscal( false, da, zx, 1 ); // $ExpectError
	zdscal( null, da, zx, 1 ); // $ExpectError
	zdscal( undefined, da, zx, 1 ); // $ExpectError
	zdscal( [], da, zx, 1 ); // $ExpectError
	zdscal( {}, da, zx, 1 ); // $ExpectError
	zdscal( ( zx: number ): number => zx, da, zx, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a complex number...
{
	const zx = new Complex128Array( 10 );

	zdscal( zx.length, 10, zx, 1 ); // $ExpectError
	zdscal( zx.length, '10', zx, 1 ); // $ExpectError
	zdscal( zx.length, true, zx, 1 ); // $ExpectError
	zdscal( zx.length, false, zx, 1 ); // $ExpectError
	zdscal( zx.length, null, zx, 1 ); // $ExpectError
	zdscal( zx.length, undefined, zx, 1 ); // $ExpectError
	zdscal( zx.length, [ '1' ], zx, 1 ); // $ExpectError
	zdscal( zx.length, {}, zx, 1 ); // $ExpectError
	zdscal( zx.length, ( zx: number ): number => zx, zx, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a Complex128Array...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal( zx.length, da, 10, 1 ); // $ExpectError
	zdscal( zx.length, da, '10', 1 ); // $ExpectError
	zdscal( zx.length, da, true, 1 ); // $ExpectError
	zdscal( zx.length, da, false, 1 ); // $ExpectError
	zdscal( zx.length, da, null, 1 ); // $ExpectError
	zdscal( zx.length, da, undefined, 1 ); // $ExpectError
	zdscal( zx.length, da, [ '1' ], 1 ); // $ExpectError
	zdscal( zx.length, da, {}, 1 ); // $ExpectError
	zdscal( zx.length, da, ( zx: number ): number => zx, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal( zx.length, da, zx, '10' ); // $ExpectError
	zdscal( zx.length, da, zx, true ); // $ExpectError
	zdscal( zx.length, da, zx, false ); // $ExpectError
	zdscal( zx.length, da, zx, null ); // $ExpectError
	zdscal( zx.length, da, zx, undefined ); // $ExpectError
	zdscal( zx.length, da, zx, [] ); // $ExpectError
	zdscal( zx.length, da, zx, {} ); // $ExpectError
	zdscal( zx.length, da, zx, ( zx: number ): number => zx ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal(); // $ExpectError
	zdscal( zx.length ); // $ExpectError
	zdscal( zx.length, da ); // $ExpectError
	zdscal( zx.length, da, zx ); // $ExpectError
	zdscal( zx.length, da, zx, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex128Array...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal.ndarray( zx.length, da, zx, 1, 0 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal.ndarray( '10', da, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( true, da, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( false, da, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( null, da, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( undefined, da, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( [], da, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( {}, da, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( ( zx: number ): number => zx, da, zx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a complex number...
{
	const zx = new Complex128Array( 10 );

	zdscal.ndarray( zx.length, 10, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, '10', zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, true, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, false, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, null, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, undefined, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, [ '1' ], zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, {}, zx, 1, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, ( zx: number ): number => zx, zx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a Complex128Array...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal( zx.length, da, 10, 1, 0 ); // $ExpectError
	zdscal( zx.length, da, '10', 1, 0 ); // $ExpectError
	zdscal( zx.length, da, true, 1, 0 ); // $ExpectError
	zdscal( zx.length, da, false, 1, 0 ); // $ExpectError
	zdscal( zx.length, da, null, 1, 0 ); // $ExpectError
	zdscal( zx.length, da, undefined, 1, 0 ); // $ExpectError
	zdscal( zx.length, da, [ '1' ], 1, 0 ); // $ExpectError
	zdscal( zx.length, da, {}, 1, 0 ); // $ExpectError
	zdscal( zx.length, da, ( zx: number ): number => zx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal.ndarray( zx.length, da, zx, '10', 0 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, true, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, false, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, null, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, undefined, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, [], 0 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, {}, 0 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, ( zx: number ): number => zx, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal.ndarray( zx.length, da, zx, 1, '10' ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, true ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, false ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, null ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, undefined ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, [] ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, {} ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, ( zx: number ): number => zx ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const zx = new Complex128Array( 10 );
	const da = 2.0;

	zdscal.ndarray(); // $ExpectError
	zdscal.ndarray( zx.length ); // $ExpectError
	zdscal.ndarray( zx.length, da ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1 ); // $ExpectError
	zdscal.ndarray( zx.length, da, zx, 1, 0, 10 ); // $ExpectError
}
